/* APLUS AI Tutor Database V1 - P6 Synthesis Transformation Expansion Batch 02 */
const APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH02 = [
{id:'P6-ST-B02-0001',type:'synthesis',skill:'because',question:'Combine using because: The pupils stayed indoors. It was raining heavily.',answer:'The pupils stayed indoors because it was raining heavily.',acceptedPatterns:['The pupils stayed indoors because it was raining heavily.'],explanation:'Because introduces the reason.',difficulty:1},
{id:'P6-ST-B02-0002',type:'synthesis',skill:'although',question:'Combine using although: The path was steep. The hikers continued.',answer:'Although the path was steep, the hikers continued.',acceptedPatterns:['Although the path was steep, the hikers continued.','The hikers continued although the path was steep.'],explanation:'Although introduces contrast.',difficulty:1},
{id:'P6-ST-B02-0003',type:'synthesis',skill:'so',question:'Combine using so: The shop was closed. We went home.',answer:'The shop was closed, so we went home.',acceptedPatterns:['The shop was closed, so we went home.'],explanation:'So introduces the result.',difficulty:1},
{id:'P6-ST-B02-0004',type:'synthesis',skill:'after',question:'Combine using after: Mei completed her homework. She watched television.',answer:'After Mei completed her homework, she watched television.',acceptedPatterns:['After Mei completed her homework, she watched television.','Mei watched television after she completed her homework.'],explanation:'After shows sequence.',difficulty:1},
{id:'P6-ST-B02-0005',type:'synthesis',skill:'before',question:'Combine using before: Amir locked the door. He left the house.',answer:'Amir locked the door before he left the house.',acceptedPatterns:['Amir locked the door before he left the house.','Before Amir left the house, he locked the door.'],explanation:'Before shows which action happened earlier.',difficulty:1},
{id:'P6-ST-B02-0006',type:'synthesis',skill:'while',question:'Combine using while: Sara was reading. Her brother was drawing.',answer:'Sara was reading while her brother was drawing.',acceptedPatterns:['Sara was reading while her brother was drawing.','While her brother was drawing, Sara was reading.'],explanation:'While connects simultaneous actions.',difficulty:1},
{id:'P6-ST-B02-0007',type:'synthesis',skill:'relative clause',question:'Combine using who: The girl won the prize. She is my cousin.',answer:'The girl who won the prize is my cousin.',acceptedPatterns:['The girl who won the prize is my cousin.'],explanation:'Who introduces information about a person.',difficulty:1},
{id:'P6-ST-B02-0008',type:'synthesis',skill:'relative clause',question:'Combine using which: I bought a bag. It has many pockets.',answer:'I bought a bag which has many pockets.',acceptedPatterns:['I bought a bag which has many pockets.','I bought a bag that has many pockets.'],explanation:'Which can refer to a thing.',difficulty:2},
{id:'P6-ST-B02-0009',type:'transformation',skill:'unless',question:'Rewrite using unless: You will get wet if you do not take an umbrella.',answer:'You will get wet unless you take an umbrella.',acceptedPatterns:['You will get wet unless you take an umbrella.'],explanation:'Unless means if not.',difficulty:2},
{id:'P6-ST-B02-0010',type:'transformation',skill:'because of',question:'Rewrite using because of: The game was cancelled because it rained heavily.',answer:'The game was cancelled because of the heavy rain.',acceptedPatterns:['The game was cancelled because of the heavy rain.'],explanation:'Because of is followed by a noun phrase.',difficulty:2},
{id:'P6-ST-B02-0011',type:'transformation',skill:'despite',question:'Rewrite using despite: Although she was tired, she completed the work.',answer:'Despite being tired, she completed the work.',acceptedPatterns:['Despite being tired, she completed the work.','She completed the work despite being tired.'],explanation:'Despite can be followed by a gerund phrase.',difficulty:3},
{id:'P6-ST-B02-0012',type:'transformation',skill:'so that',question:'Rewrite using so that: He spoke clearly because he wanted everyone to understand.',answer:'He spoke clearly so that everyone could understand.',acceptedPatterns:['He spoke clearly so that everyone could understand.'],explanation:'So that expresses purpose.',difficulty:2},
{id:'P6-ST-B02-0013',type:'transformation',skill:'too...to',question:'Rewrite using too...to: The box was so heavy that Ali could not lift it.',answer:'The box was too heavy for Ali to lift.',acceptedPatterns:['The box was too heavy for Ali to lift.'],explanation:'Too + adjective + for + person + to-infinitive expresses excessive degree.',difficulty:3},
{id:'P6-ST-B02-0014',type:'transformation',skill:'enough',question:'Rewrite using enough: The room was large. It could hold all the pupils.',answer:'The room was large enough to hold all the pupils.',acceptedPatterns:['The room was large enough to hold all the pupils.'],explanation:'Adjective + enough + to-infinitive expresses sufficient degree.',difficulty:2},
{id:'P6-ST-B02-0015',type:'transformation',skill:'passive voice',question:'Rewrite in the passive voice: The pupils planted the trees.',answer:'The trees were planted by the pupils.',acceptedPatterns:['The trees were planted by the pupils.'],explanation:'The object becomes the passive subject and takes past passive.',difficulty:2},
{id:'P6-ST-B02-0016',type:'transformation',skill:'passive voice',question:'Rewrite in the passive voice: The school organises the event every year.',answer:'The event is organised by the school every year.',acceptedPatterns:['The event is organised by the school every year.'],explanation:'A regular present action uses the present passive.',difficulty:2},
{id:'P6-ST-B02-0017',type:'transformation',skill:'reported speech',question:'Rewrite in reported speech: Jane said, "I am nervous."',answer:'Jane said that she was nervous.',acceptedPatterns:['Jane said that she was nervous.'],explanation:'Am changes to was after a past reporting verb.',difficulty:2},
{id:'P6-ST-B02-0018',type:'transformation',skill:'reported question',question:'Rewrite in reported speech: "What time does the shop close?" Ben asked.',answer:'Ben asked what time the shop closed.',acceptedPatterns:['Ben asked what time the shop closed.'],explanation:'Reported questions use statement word order.',difficulty:3},
{id:'P6-ST-B02-0019',type:'transformation',skill:'reported command',question:'Rewrite in reported speech: Mum said, "Do not touch the wet paint."',answer:'Mum told me not to touch the wet paint.',acceptedPatterns:['Mum told me not to touch the wet paint.','Mum told us not to touch the wet paint.'],explanation:'Negative reported commands use told + object + not to-infinitive.',difficulty:3},
{id:'P6-ST-B02-0020',type:'transformation',skill:'comparative',question:'Rewrite using not as...as: The blue route is longer than the red route.',answer:'The red route is not as long as the blue route.',acceptedPatterns:['The red route is not as long as the blue route.'],explanation:'The shorter item can be described with not as + adjective + as.',difficulty:2}
];
window.APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH02 = APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH02;